UPDATE endpoints e SET description = v.description, description_hy = v.description_hy, params = v.params, response_example = v.response_example, updated_at = NOW() FROM (VALUES
('POST', '/legacy-api/set_patient_schedule', 'Registers a new patient visit/appointment. The visit is created with status Pending. visit_id (visit number), visit_date_end (visit_date + visit_duration minutes), the video consultation link, doctor_id (looked up from doctor_ssn among enabled doctors, otherwise 0) and the branch name (looked up from branch_office_id) are generated by the API. Services are saved as a list in the visit''s service list. Send fields as application/x-www-form-urlencoded. Requires header: Authorization: Bearer <static API token>.', 'Գրանցում է հիվանդի նոր այց/հանդիպում՝ Pending կարգավիճակով։ API-ն ինքնուրույն ստեղծում է այցի համարը (visit_id), visit_date_end-ը (visit_date + visit_duration րոպե), տեսազանգի հղումը, doctor_id-ն (գտնվում է doctor_ssn-ով ակտիվ բժիշկների մեջ, հակառակ դեպքում՝ 0) և մասնաճյուղի անունը (branch_office_id-ով)։ Ծառայությունները պահվում են այցի ծառայությունների ցանկում։ Դաշտերն ուղարկել application/x-www-form-urlencoded ձևաչափով։ type_of_visit_id՝ 1 = Խորհրդատվություն (կանխադրված), 3 = Ախտորոշիչ, 5 = Սարքավորման տրամադրում։ payment_type_id (կանխադրված՝ 3)՝ 1 = Պետպատվեր, 2 = Ապահովագրություն (Սոց. փաթեթ), 3 = Վճարովի, 4 = Ապահովագրություն, 5 = Քարտի շրջանառություն, 6 = Դոնոր, 7 = Համընդհանուր ապահովագրություն, 8 = ԱՊՊԱ, 9 = Ադմինիստրացիա։ Սխալի դեպքում՝ 403 և [{"status":"0","message":"..."}]։ Սխալ կամ բացակայող տոկենի դեպքում վերադարձվում է «Access denied...» տեքստը։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։', '{"visit_date": "string (required) - Visit start, format YYYY-MM-DD HH:MM:SS", "visit_duration": "string (optional) - Visit length in minutes (default 30)", "type_of_visit_id": "string (optional) - Visit type: 1 = Consultation (default), 3 = Diagnostic, 5 = Equipment supply", "type_of_visit": "string (optional)", "patient_ssn": "string (required)", "patient_document": "string (optional)", "patient_name": "string (required)", "patient_surname": "string (required)", "patient_middlename": "string (optional)", "patient_birthday": "string (optional) - Format YYYY-MM-DD", "patient_gender": "string (optional)", "patient_phone_mobile": "string (required)", "patient_mail": "string (optional)", "complaints": "string (optional)", "insurance_id": "string (optional)", "insurance_name": "string (optional)", "insurance_policy_no": "string (optional)", "department_id": "string (required)", "department_name": "string (optional)", "doctor_ssn": "string (required)", "doctor_name": "string (optional)", "note": "string (optional)", "have_a_referral": "string (optional) - format: 0", "payment_type_id": "string (optional) - Payment type id (default 3). 1 = State order, 2 = Insurance (Social package), 3 = Paid, 4 = Insurance, 5 = Card turnover, 6 = Donor, 7 = Universal insurance, 8 = Motor insurance (MTPL), 9 = Administration", "branch_office_id": "string (optional) - id from GET /get_branch; the branch name is looked up and stored automatically", "services": "string (optional) - JSON array of {service_id, service_name} objects, service_id from GET /get_hospital_services (service_local_id)"}', '[
  {
    "status": "1",
    "message": "Registration Successfully",
    "row_id": 1,
    "branch_office_id": "1",
    "branch_office": "DST Բժշկական համալիր"
  }
]'),
('POST', '/legacy-api/set_patient_schedule_update', 'Reschedules an existing patient visit (schedule_id is the row_id returned by POST /set_patient_schedule). The visit status is reset to Pending and the queue confirmation is cleared. Visit statuses: Pending (new or rescheduled), Canceled. Requires header: Authorization: Bearer <static API token>.', 'Տեղափոխում է հիվանդի առկա այցը (schedule_id-ն POST /set_patient_schedule-ի վերադարձրած row_id-ն է) նոր ամսաթվի։ Կարգավիճակը վերադառնում է Pending, հերթի հաստատումը մաքրվում է։ Ամսաթվի ձևաչափ՝ YYYY-MM-DD HH:MM:SS։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։', '{"schedule_id": "string (required) - format: 1", "visit_date": "string (required) - format: 2026-07-02 11:00:00"}', '[
  {
    "status": "1",
    "message": "The queue has been successfully edited"
  }
]'),
('POST', '/legacy-api/set_patient_schedule_cancel', 'Cancels an existing patient visit (schedule_id is the row_id returned by POST /set_patient_schedule). The visit status becomes Canceled and cancelled_date and cancelled_by are saved. Dates use the format YYYY-MM-DD HH:MM:SS. Requires header: Authorization: Bearer <static API token>.', 'Չեղարկում է հիվանդի առկա այցը (schedule_id-ն POST /set_patient_schedule-ի վերադարձրած row_id-ն է)։ Կարգավիճակը դառնում է Canceled, պահվում են cancelled_date-ը և cancelled_by-ը։ Ամսաթվի ձևաչափ՝ YYYY-MM-DD HH:MM:SS։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։', '{"schedule_id": "string (required) - format: 1", "cancelled_by": "string (required) - format: 1", "cancelled_date": "string (required) - format: 2026-07-01 09:00:00"}', '[
  {
    "status": "1",
    "message": "Queue canceled successfully",
    "schedule_id": "1"
  }
]'),
('POST', '/legacy-api/set_doctor_block_time', 'Creates a blocked time entry for a doctor (e.g. vacation, unavailability). Requires header: Authorization: Bearer <static API token>.', 'Ստեղծում է բժշկի համար արգելափակված ժամանակի գրառում (օրինակ՝ արձակուրդ կամ բացակայություն)։ doctor_id-ն պարտադիր չէ. բացակայության դեպքում այն գտնվում է doctor_ssn-ով (եթե բժիշկը չի գտնվել՝ 0)։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։', '{"doctor_id": "string (optional) - Optional. If omitted, it is looked up from doctor_ssn (0 if the doctor is not found)", "doctor_ssn": "string (required) - format: 0001", "block_start": "string (required) - format: 2026-08-01 09:00:00", "block_end": "string (required) - format: 2026-08-01 12:00:00", "note": "string (optional)"}', '[
  {
    "status": "1",
    "id": 1,
    "message": "The data has been created successfully"
  }
]'),
('GET', '/legacy-api/get_doctor_block_time', 'Returns a doctor''s upcoming blocked time slots and active appointments combined (excludes completed/cancelled visits and hidden blocks), useful for checking availability. Requires header: Authorization: Bearer <static API token>. Example request: GET /legacy-api/get_doctor_block_time?doctor_ssn=0001', 'Վերադարձնում է բժշկի առաջիկա արգելափակված ժամանակահատվածները և ակտիվ այցերը միասին (չեն ներառվում ավարտված/չեղարկված այցերը և թաքցված արգելափակումները)։ Օգտակար է հասանելիությունը ստուգելու համար։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։ Հարցման օրինակ՝ GET /legacy-api/get_doctor_block_time?doctor_ssn=0001', '{"doctor_ssn": "string (required)"}', '[
  {
    "id": 1,
    "doctor_ssn": "0001",
    "block_start": "2026-08-01 09:00:00",
    "block_end": "2026-08-01 12:00:00",
    "type": "block"
  }
]'),
('GET', '/legacy-api/get_branch', 'Returns active hospital branches/offices. Omit id to get the full list, or pass it to fetch a single branch. Use the returned id as branch_office_id when calling POST /set_patient_schedule. Requires header: Authorization: Bearer <static API token>. Example request: GET /legacy-api/get_branch?id=1', 'Վերադարձնում է հիվանդանոցի ակտիվ մասնաճյուղերը/գրասենյակները։ Առանց id-ի վերադարձնում է ամբողջ ցանկը, id-ով՝ մեկ մասնաճյուղ։ Վերադարձված id-ն օգտագործեք որպես branch_office_id՝ POST /set_patient_schedule կանչելիս։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։ Հարցման օրինակ՝ GET /legacy-api/get_branch?id=1', '{"id": "integer (optional) - Optional — filters to a single branch"}', '[
  {
    "id": 1,
    "code": 1,
    "text_am": "DST Բժշկական համալիր",
    "text_en": "",
    "text_ru": "",
    "letter": "G",
    "address": "Սաղավանյան 76",
    "phone": "010342058",
    "gps_location": "40.21025164520757, 44.4390024727424",
    "medcard": 1,
    "hospital_id": 0,
    "mail": "",
    "discount_lab": 0,
    "discount_clinic": 0
  }
]'),
('GET', '/legacy-api/get_hospital_doctors', 'Returns doctors available for mobile booking (access_of_mobile = 1, enabled = 1), including their default consultation/telemed service prices resolved via structure_hospital_services. Requires header: Authorization: Bearer <static API token>.', 'Վերադարձնում է բջջային հավելվածով գրանցման համար հասանելի բժիշկներին (access_of_mobile = 1, enabled = 1)՝ ներառյալ խորհրդատվության և հեռուստաբժշկական ծառայության լռելյայն գները, որոնք որոշվում են structure_hospital_services աղյուսակից։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։', NULL::text, '[
  {
    "id": 1,
    "user_id": "1",
    "user_document": "",
    "user_ssn": "0001",
    "user_name": "Test",
    "user_surname": "Doctor",
    "user_middlename": "",
    "user_birthday": "1980-01-01 00:00:00",
    "user_gender": "M",
    "user_phone": "+37499000000",
    "user_mail": "doctor@example.com",
    "department_name_id": 1,
    "department_name": "General",
    "cabinet": "101",
    "profession_id": 1,
    "profession": "General Practitioner",
    "position": "Doctor",
    "academic_degree": "MD",
    "rating": 0,
    "rating_dislike": 0,
    "branch_id": 1,
    "branch_office": "DST Բժշկական համալիր",
    "defoult_cons_price": 5000,
    "defoult_telemed_cons_price": 4000,
    "teleconsultation_enabled": 1,
    "about_us": "",
    "user_image": ""
  }
]'),
('GET', '/legacy-api/get_hospital_services', 'Returns active/enabled hospital services, optionally filtered by department. Requires header: Authorization: Bearer <static API token>. Example request: GET /legacy-api/get_hospital_services?department_id=1', 'Վերադարձնում է հիվանդանոցի ակտիվ/միացված ծառայությունները՝ ըստ ցանկության ֆիլտրված բաժանմունքով։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։ Հարցման օրինակ՝ GET /legacy-api/get_hospital_services?department_id=1', '{"department_id": "integer (optional) - Optional — filters to a single department''s services"}', '[
  {
    "id": 1,
    "department_id": 1,
    "service_local_id": "S001",
    "service_name": "General Consultation",
    "service_price": 5000
  }
]'),
('GET', '/legacy-api/get_hospital_departments', 'Returns visible departments/specializations available for the medcard system (visible = 1, medcard = 1). Requires header: Authorization: Bearer <static API token>.', 'Վերադարձնում է medcard համակարգի համար հասանելի տեսանելի բաժանմունքները/մասնագիտացումները (visible = 1, medcard = 1)։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։', NULL::text, '[
  {
    "id": 1,
    "global_service_code": "GS001",
    "global_service": "General Medicine",
    "department_id": 1,
    "department_name_am": "",
    "department_name_en": "General Medicine",
    "department_name_ru": "",
    "department_specialization_id": 1,
    "department_specialization": "General Practice",
    "is_tool": 0,
    "branch_id": 1,
    "branch_name": "DST Բժշկական համալիր",
    "queuing": 1,
    "location": "Floor 1",
    "registration_location": "Reception Desk 1"
  }
]'),
('GET', '/legacy-api/get_hospital_doctor_work_time', 'Returns doctors'' weekly work schedules: working days, work hours, break, admission duration, and the telemedicine / state / VIP time windows. Omit doctor_ssn to get all schedules. Requires header: Authorization: Bearer <static API token>. Example request: GET /legacy-api/get_hospital_doctor_work_time?doctor_ssn=0001', 'Վերադարձնում է բժիշկների շաբաթական աշխատանքային գրաֆիկը՝ աշխատանքային օրեր, ժամեր, ընդմիջում, ընդունելության տևողություն, ինչպես նաև հեռուստաբժշկական / պետական / VIP ժամանակահատվածները։ Առանց doctor_ssn-ի վերադարձնում է բոլոր գրաֆիկները։ Պահանջվում է վերնագիր՝ Authorization: Bearer <static API token>։ Հարցման օրինակ՝ GET /legacy-api/get_hospital_doctor_work_time?doctor_ssn=0001', '{"doctor_ssn": "string (optional) - Optional — filters to a single doctor"}', '[
  {
    "id": 1,
    "doctor_id": "1",
    "doctor_ssn": "0001",
    "days_of_the_week": "1,2,3,4,5",
    "work_start": "09:00:00",
    "work_end": "18:00:00",
    "break_start": "13:00:00",
    "break_duration": 60,
    "duration_of_admission": 30,
    "telemed_start": "16:00:00",
    "telemed_end": "18:00:00",
    "state_start": "09:00:00",
    "state_end": "13:00:00",
    "vip_start": "14:00:00",
    "vip_end": "16:00:00"
  }
]')
) AS v(method, path, description, description_hy, params, response_example) WHERE e.method = v.method AND e.path = v.path;
